'use strict';

// VARIABLES //

var RE_RECORD_PATH = /^([a-z0-9]+(?:-[a-z0-9]+)*)\/([a-z0-9]+(?:-[a-z0-9]+)*)\/(\d{4}_\d{2}_\d{2}T\d{2}_\d{2}_\d{2}Z)__sha256_([0-9a-f]{64})\.json\.gz$/;


// MAIN //

/**
* Parses and validates a stored record path.
*
* @param {string} value - path relative to the data directory
* @returns {Object} parsed components
*/
function parsePath( value ) {
	var match = RE_RECORD_PATH.exec( value );

	if ( !match ) {
		throw new Error( 'Invalid stored record path: ' + value );
	}
	return {
		'libraryId': match[ 1 ],
		'sourceId': match[ 2 ],
		'filenameTimestamp': match[ 3 ],
		'reportSha256': match[ 4 ]
	};
}


// EXPORTS //

module.exports = parsePath;
